import * as React from 'react';
import { act, cleanup, render } from '@testing-library/react';
import { afterEach, describe, it, expect } from 'vitest';
import { Slot } from './slot';

// Regression tests for https://github.com/radix-ui/primitives/issues/3799
// ("Error: Maximum update depth exceeded" in React 19). `Slot` created a brand-new
// composed ref callback on every render. React 19 re-invokes ref callbacks whose
// identity changed between renders, so a ref callback that triggers a render
// (e.g. via a state update, as Slate/Plate do while typing) re-attached the ref
// on every render: ref callback -> update -> re-render -> new ref identity ->
// ref callback -> ... until React hit the maximum nested update depth.
describe('Slot ref stability', () => {
  afterEach(cleanup);

  it('does not cause an infinite render loop when attaching the ref triggers a render', () => {
    let renderCount = 0;

    function App() {
      renderCount++;
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      const ref = React.useCallback((node: HTMLElement | null) => {
        if (node) forceRender();
      }, []);

      return (
        <Slot ref={ref}>
          <button type="button">Click me</button>
        </Slot>
      );
    }

    expect(() => render(<App />)).not.toThrow();
    expect(renderCount).toBeLessThan(25);
  });

  it('passes a single stable composed ref to the child across re-renders', () => {
    const refIdentities = new Set<unknown>();
    let bump!: () => void;

    const Child = React.forwardRef<HTMLButtonElement>(function Child(_props, ref) {
      refIdentities.add(ref);
      return <button type="button" ref={ref} />;
    });

    function App() {
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      bump = forceRender;
      const forwardedRef = React.useRef<HTMLButtonElement>(null);
      return (
        <Slot ref={forwardedRef}>
          <Child />
        </Slot>
      );
    }

    render(<App />);
    act(() => bump());
    act(() => bump());
    expect(refIdentities.size).toBe(1);
  });
});

parts.text:
The bug has been accurately reproduced as reported:
- Test 1: `Error: Maximum update depth exceeded. This can happen when a component repeatedly calls setState...` — same as the bug report.
- Test 2: 3 different ref identities were passed to the child across 3 renders (one per render) — this proves the instability of the composed ref.

**Confirming the root cause:** `Slot` calls `composeRefs(forwardedRef, slottableElementRef)` inside the render function, producing a new ref callback identity on every render. React 19 re-attaches ref callbacks whose identity has changed. If the ref's callback schedules a render (setState), that causes re-render → new ref identity → re-attach → callback → setState → ... → maximum update depth exceeded. In the bug report's scenario, Slate/Plate's editable ref and the composed refs of Radix popover/tooltip inside editable trigger this every time you type.

Next, apply the fix to slot.tsx (following the upstream #3899 approach, matching the repo's style):

1. Change the import from `composeRefs` to `useComposedRefs`.
2. Hoist the computation of `slottableElementRef` and the call to `useComposedRefs` before the early return, so the hook is called unconditionally.
3. Use `composedRef` in mergedProps.

Current slot.tsx lines 74–81:

```tsx
    const slottableElementRef = getElementRef(slottableElement);
    const composedRefs = composeRefs(forwardedRef, slottableElementRef);
    const mergedProps = mergeProps(slotProps, slottableElement.props ?? {});

    // Do not pass ref to React.Fragment for React 19 compatibility
    if (slottableElement.type !== React.Fragment) {
      mergedProps.ref = forwardedRef ? composedRefs : slottableElementRef;
    }
```

